def get_sensor_ip_from_name(sensor_name,date = datetime.datetime.now(datetime.timezone.utc)):
    """Returns  the sensor_ip from the name for a given date range fixes the fact that NUCs and 
    IPs were changed due to failures.
    Catalina was 12/10, GMM was 02/14"""

    SENSOR_COMMON_NAMES = {"seadog03.its.ntia.gov":"Midway",
                       "seadog04.its.ntia.gov":"HU",
                       "seadog05.its.ntia.gov":"NIT",
                       "seadog07.its.ntia.gov":"GMM",
                       "seadog08.its.ntia.gov":"Pendleton",
                       "seadog09.its.ntia.gov":"Catalina-Omni",
                       "seadog19.its.ntia.gov":"Catalina-Directional",
                       "seadog06.its.ntia.gov":"CBBT-Omni",
                       "seadog16.its.ntia.gov":"CBBT-Directional",
                       "seadog10.its.ntia.gov":"Oceana",
                       "seadog32.its.ntia.gov":"PtLoma-Omni",
                       "seadog42.its.ntia.gov":"PtLoma-Directional"}
    
    if date > pd.to_datetime("2024-12-10 17:00",utc=True) and "Catalina" in sensor_name :
        SENSOR_COMMON_NAMES = {"seadog12.its.ntia.gov":"Catalina-Omni",
                        "seadog22.its.ntia.gov":"Catalina-Directional"}
    if date > pd.to_datetime("2025-02-14",utc=True) and "GMM" in sensor_name:
        SENSOR_COMMON_NAMES = {"seadog14.its.ntia.gov":"GMM"}
    SENSOR_IP_NAMES = {value:key for key,value in SENSOR_COMMON_NAMES.items() }
    assert sensor_name in SENSOR_IP_NAMES.keys(), f"Invalid sensor name {sensor_name}"
    return SENSOR_IP_NAMES[sensor_name]

def roll_max(query,reference):
    qidx = np.diff(query).argmax()
    ridx = np.diff(reference).argmax()
    query_shift = np.roll(query,ridx-qidx)
    return query_shift.flatten()

def lin_sum(array):
    alin = 10**(array/10)
    alin = alin.sum()
    return 10*np.log10(alin)

def fetch_lte_template(file_path = LTE_TTI_CONFIG_PATH):
    ## Importing the Resource Element Utilization of LTE
    # The LTE xlsx were built by transcribing from: https://dhagle.in/LTE.php
    # The LTE xslx contain positional RE values: 1 for Control Channel, d for Downlink Shared Channel,
    # u for Uplink Shared Channel, r for reserved Channel


    base =pd.read_excel(file_path,sheet_name = 0,header=None) 
    mid = pd.read_excel(file_path,sheet_name = 1,header=None)

    bc = base.replace(['d','u','r'],[0,0,0])
    mc = mid.replace(['d','u','r'],[0,0,0])

    bce = pd.concat([bc,bc,bc,bc],axis=1)
    bce = bce.T.sort_index().reset_index(drop=True).T

    mce = pd.concat([mc,mc,mc,mc],axis=1)
    mce = mce.T.sort_index().reset_index(drop=True).T

    #ps_pfp_20 is the time axis RE utilization for 10 MHz of a 20 MHz allocation
    # RE utilization is symmetric for the lower and upper portion of an allocation 
    ps_pfp_20 = 47*bce.sum(axis=0)+3*mce.sum(axis=0)
    ps_pfp_20 = ps_pfp_20.replace(0,0.1)

    #ps_pfp_10 is the time axis RE utilization for the 10 MHz allocation
    # RE utilization is symmetric for the lower and upper portion of an allocation 

    ps_pfp_10 = 44*bce.sum(axis=0)+6*mce.sum(axis=0)
    ps_pfp_10 = ps_pfp_10.replace(0,0.1)

    #ps_psd_20 is the frequency projection of RE utilization for the Lower 10 MHz of the 20 MHz allocation, 
    #Note that this is not symmetric for the Upper 10 MHz. the Upper complement is  ps_psd_20[::-1]
    ps_psd_20 = np.append(np.tile(bc.sum(axis=1),47),np.tile(mc.sum(axis=1),3))

    #ps_psd_10 is the frequency project of RE utilization of the 10 MHz allocation 
    ps_psd_10 = np.append(np.append(np.tile(bc.sum(axis=1),22),np.tile(mc.sum(axis=1),6)),np.tile(bc.sum(axis=1),22))
    #Frequency components of the RE utilization, note that the Upper 10 of 20 MHz compliment can be defined
    #with a frequency shift
    ps_freq_10 = np.arange(-15e3*300+7.5e3,15e3*300,15e3)
    ps_freq_20 = np.arange(-15e3*600+7.5e3,0,15e3)+5e6   

    output ={}
    output["ps_freq_10"] = ps_freq_10
    output["ps_freq_20"] = ps_freq_20
    output["ps_pfp_20"] = ps_pfp_20
    return output

#normalizes a vector that is in form of a pandas Series/DataFrame
def norm(x):
    xmin = x.min()
    xmax = x.max()
    return (x-xmin)/(xmax-xmin)
#input x: the PFP vector as row in a Pandas DataFrame
#input r: the reference waveform as a Pandas Series
    #in this case LTE Config 2, Special Config 7, scaled from 1 - 0 on the same vector axis as a pfp
#windowsize is the integer to perform a rolling max over, 28 corresponds to 1 slot//
#norm(x) returns a normalized vector. 

def corr_coeff_window(x,r,windowsize = 28):
    start_int = windowsize-1
    xr = norm(x).rolling(window=windowsize).max()[start_int:]
    rr = r.rolling(window=windowsize).max()[start_int:]
    correlation = signal.correlate(rr-np.mean(rr),xr-np.mean(xr))
    lag = correlation.argmax()-(len(rr) - 1)
    x_corrected = np.roll(x,lag)
    return x_corrected
