# Module Classes
class DataProduct():
    """Wraps the sea_ingest dictionary of pandas data frames that represents a single acquistion of the sea sensor  """
    def __init__(self,data,**options) -> None:
        if isinstance(data,str):
            if re.search(".sigmf",data):
                self.data = sea_ingest.read_seamf(data)
                self.path = data
        elif isinstance(data,dict):
            self.data = data
            self.path = data

        self.psd_statistics = self.data['psd'].droplevel("datetime").droplevel("frequency").index.unique().tolist()
        self.frequencies = self.data['psd'].droplevel("datetime").droplevel("capture_statistic").index.unique().tolist()
        self.timestamps = self.data['psd'].droplevel("frequency").droplevel("capture_statistic").index.unique().tolist()
        self.pvt_detectors = self.data['pvt'].droplevel("datetime").droplevel("frequency").index.unique().tolist()
        self.pfp_detectors = self.data['pfp'].droplevel("datetime").droplevel("frequency").droplevel('capture_statistic').index.unique().tolist()
        self.pfp_statistics =self.data['pfp'].droplevel("datetime").droplevel("frequency").droplevel('detector').index.unique().tolist()
        self.channel_indices = self.data['channel_metadata'].index.tolist()
        self.gains  = self.data["channel_metadata"].droplevel('datetime')["cal_gain_dB"]
        self.noise_figures  = self.data["channel_metadata"].droplevel('datetime')["cal_noise_figure_dB"]
        
    def get_channel_index(self,channel):
        # Handle Channel Selection
        if isinstance(channel,int):
            channel_index = list(self.channel_indices[channel])
        elif isinstance(channel,float):
            channel_index = list(self.channel_indices[self.frequencies.index(channel)])
        else:
            channel_index = channel
        return channel_index

    def get_xy_data(self,channel,data_product,capture_statistic=None,detector=None):
        """Returns x_values, y_values for the selected channel, data_product and optional capture_statistic and detector"""
        channel_index = self.get_channel_index(channel)
        #print(f"Channel index is {channel_index}")
        if data_product == 'psd':
            assert capture_statistic != None, "must enter a capture statistic, see self.psd_statistics for options"
            index = channel_index
            index.append(capture_statistic)
            index = tuple(index)
            x_values = self.data['psd'].xs(index).index
            y_values = self.data['psd'].xs(index).values
            return x_values,y_values
        elif data_product == 'pfp':
            assert capture_statistic != None, "must enter a capture statistic, see self.pfp_statistics for options"
            assert detector != None, "must enter a detector, see self.pfp_detectors for options"
            index = channel_index
            index.append(capture_statistic)
            index.append(detector)
            index = tuple(index)
            x_values = self.data['pfp'].xs(index).index
            y_values = self.data['pfp'].xs(index).values
            return x_values,y_values
        elif data_product == 'pvt':
            assert detector != None, "must enter a detector, see self.pvt_detectors for options"
            index = channel_index
            index.append(detector)
            index = tuple(index)
            x_values = self.data['pvt'].xs(index).index
            y_values = self.data['pvt'].xs(index).values
            return x_values,y_values
        elif data_product == 'apd':
            index = channel_index
            index = tuple(index)
            x_values = self.data['apd'].xs(index).values
            y_values = self.data['apd'].xs(index).index
            return x_values,y_values 
        else:
            print(f"Unable to complete the request {locals()} did not have the required information")
            return None, None   
        
class DayBlock():
    def __init__(self, repository=None, sensor_name=None,date =None,file_path =None) -> None:
        if file_path:
            self.path = file_path
            basename = os.path.basename(file_path)
            match = re.match(DATABLOCK_PATTERN,basename)
            sensor_name = match.groupdict()["sensor_hostname"]
            date = match.groupdict()["date"]
        else:
            self.path = os.path.join(repository,f"{date}_{sensor_name}.zip")
        if sensor_name in SENSOR_COMMON_NAMES.keys():
            self.sensor_hostname = sensor_name
            self.sensor = SENSOR_COMMON_NAMES[sensor_name]
        elif sensor_name in SENSOR_COMMON_NAMES.values():
            self.sensor_hostname = get_sensor_ip_from_name(sensor_name)
            self.sensor = sensor_name
        self.date = date
        self.data = sea_ingest.read_seamf_zipfile(self.path)
        self.psd_statistics = self.data['psd'].droplevel("datetime").droplevel("frequency").index.unique().tolist()
        self.frequencies = self.data['psd'].droplevel("datetime").droplevel("capture_statistic").index.unique().tolist()
        self.timestamps = self.data['psd'].droplevel("frequency").droplevel("capture_statistic").index.unique().tolist()
        self.pvt_detectors = self.data['pvt'].droplevel("datetime").droplevel("frequency").index.unique().tolist()
        self.pfp_detectors = self.data['pfp'].droplevel("datetime").droplevel("frequency").droplevel('capture_statistic').index.unique().tolist()
        self.pfp_statistics =self.data['pfp'].droplevel("datetime").droplevel("frequency").droplevel('detector').index.unique().tolist()
        self.channel_indices = self.data['channel_metadata'].index.tolist()
        self.gains  = self.data["channel_metadata"].droplevel('datetime')["cal_gain_dB"]
        self.noise_figures  = self.data["channel_metadata"].droplevel('datetime')["cal_noise_figure_dB"]
        self.number_collects = len(self.data['sweep_metadata'])
        self.number_channels = len(self.frequencies)

    def get_single(self,single_selector):
        """Returns a  dictionary of a single collect"""
        if isinstance(single_selector,str):
            try:
                single_selector = pd.to_datetime(single_selector,utc=True)
            except:
                try:
                    single_selector = int(single_selector)
                except:
                    print(f"Could not decode {single_selector}")
                    raise
        if isinstance(single_selector,pd._libs.tslibs.timestamps.Timestamp):
            single_selector = np.argmin(abs(pd.to_datetime(self.data['sweep_metadata']['datetime'])-single_selector))

        start_index = single_selector*self.number_channels
        stop_index = (single_selector+1)*self.number_channels
        out_data = {} 
        out_data["psd"] = self.data["psd"][start_index*len(self.psd_statistics):stop_index*len(self.psd_statistics)]
        out_data["pvt"] = self.data["pvt"][start_index*len(self.pvt_detectors):stop_index*len(self.pvt_detectors)]
        out_data["pfp"] = self.data["pfp"][start_index*len(self.pfp_detectors)*len(self.pfp_statistics):stop_index*len(self.pfp_detectors)*len(self.pfp_statistics)]
        out_data["apd"] = self.data["apd"][start_index:stop_index]
        out_data["channel_metadata"] = self.data["channel_metadata"][start_index:stop_index]
        out_data["sweep_metadata"]= self.data["sweep_metadata"][single_selector:single_selector+1]
        sensor_metadata = dict(self.data["sensor_metadata"])
        sensor_metadata.update({"sensor":self.sensor,"sensor_hostname":self.sensor_hostname,"date":self.date})
        out_data["sensor_metadata"] = sensor_metadata
        return out_data
    
    def get_day_psd(self,capture_statistic = "mean", save = False,save_type = 'csv'):
        """Returns a pandas dataframe with index = 'sweep_timestamp' and columns = Frequency"""
        sweep_times = self.data["sweep_metadata"]["datetime"].unique()
        data_list = []
        for sweep_index,sweep_time in enumerate(sweep_times):
            slice_data = self.get_single(sweep_index)
            data_product = DataProduct(slice_data)
            data_dict = {}
            data_dict["sweep_timestamp"]=sweep_time

            for frequency in data_product.frequencies:
                columns,values = data_product.get_xy_data(data_product="psd",channel=frequency,capture_statistic=capture_statistic)
                columns = columns+frequency
                data_dict.update(dict(zip(columns,values)))
            data_list.append(data_dict)
        psd_df = pd.DataFrame(data_list)
        psd_df["sweep_timestamp"] = pd.to_datetime(psd_df["sweep_timestamp"])
        psd_df=psd_df.set_index("sweep_timestamp")
        if save:
            if re.search("csv",save_type,re.IGNORECASE):
                psd_df.to_csv(save)
            elif re.search("feather",save_type,re.IGNORECASE):
                psd_df.to_feather(save)
            elif re.search("parquet",save_type):
                psd_df.to_parquet(save)
            elif re.search("pickle",save_type,re.IGNORECASE):
                psd_df.to_pickle(save)
        return psd_df
    
    def get_aligned_pfp(self,channel,capture_statistic='mean',detector='rms',save = False,save_type='csv'):
        """Returns a dataframe with sweep_timestamp, channel,  and an aligned pfp stream """
        if channel in self.frequencies:
            frequency = channel
        elif isinstance(channel,int):
            frequency = self.frequencies[channel]
        else:
            frequency = float(channel)

        template = fetch_lte_template()
        ps_pfp_20 = template['ps_pfp_20']
        dm = self.data['pfp'].xs((frequency,capture_statistic,detector),level=('frequency','capture_statistic','detector'))
        droll = dm.apply(lambda x: roll_max(x,ps_pfp_20),axis=1,result_type='expand')
        droll=droll.T.apply(lambda x: corr_coeff_window(x,LTE_27)).T
        if save:
            if re.search("csv",save_type,re.IGNORECASE):
                droll.to_csv(save)
            elif re.search("feather",save_type,re.IGNORECASE):
                droll.to_feather(save)
            elif re.search("parquet",save_type):
                droll.to_parquet(save)
            elif re.search("pickle",save_type,re.IGNORECASE):
                droll.to_pickle(save)
        return droll

    def get_day_aligned_pfp(self,capture_statistic='mean',detector='rms',save = False,save_type='csv'):
        """Returns a dataframe with sweep_timestamp, channel,  and an aligned pfp stream """
        template = fetch_lte_template()

        for channel_index,frequency in enumerate(self.frequencies):
            ps_pfp_20 = template['ps_pfp_20']
            dm = self.data['pfp'].xs((frequency,capture_statistic,detector),level=('frequency','capture_statistic','detector'))
            droll = dm.apply(lambda x: roll_max(x,ps_pfp_20),axis=1,result_type='expand')
            droll = droll.T.apply(lambda x: corr_coeff_window(x,LTE_27)).T
            droll.insert(0,"frequency",frequency*np.ones(len(dm.index)))
            if channel_index == 0:
                day_store = droll.copy()
            else:
                day_store = pd.concat([day_store,droll])
        if save:
            if re.search("csv",save_type,re.IGNORECASE):
                day_store.to_csv(save)
            elif re.search("feather",save_type,re.IGNORECASE):
                day_store.to_feather(save)
            elif re.search("parquet",save_type):
                day_store.to_parquet(save)
            elif re.search("pickle",save_type,re.IGNORECASE):
                day_store.to_pickle(save)
        return day_store

        
          
class SummaryTable():
    def __init__(self,data,**options):
        if isinstance(data,str):
            self.data = pd.read_csv(data)
        elif isinstance(data,pd.core.frame.DataFrame):
            self.data =data
        self.data['timestamp'] = self.data['timestamp'].apply(pd.to_datetime)
        self.data['acquisition_timestamp'] = self.data['acquisition_timestamp'].apply(pd.to_datetime)
        self.data['PAPR'] = self.data['max']-self.data["mean"]
        self.sensor_names = self.data["sensor_name"].unique()
        self.sensor_hostnames = self.data["sensor_hostname"].unique()
        self.channel_frequencies = self.data["channel_frequency_mhz"].unique()
        
    def get_sensor_data(self,sensor):
        if sensor in self.sensor_hostnames:
            return self.data[self.data['sensor_hostname']==sensor]
        elif sensor in self.sensor_names:
            return self.data[self.data['sensor_name']==sensor]
        else:
            return self.data
            
    def get_sensor_channel_data(self,sensor,channel):
        if isinstance(channel,int):
            frequency = self.channel_frequencies[channel]
        elif channel in self.channel_frequencies:
            frequency = channel
        elif channel in 1e6*self.channel_frequencies:
            frequency = channel/1e6
            
        if sensor in self.sensor_hostnames:
            return self.data[(self.data['sensor_hostname']==sensor)&(self.data['channel_frequency_mhz']==frequency) ]
        elif sensor in self.sensor_names:
            return self.data[(self.data['sensor_name']==sensor)&(self.data['channel_frequency_mhz']==frequency) ]
        else:
            return self.data
        
    def get_sensor_channel_daterange_data(self,start_date,stop_date,sensor,channel):
        if isinstance(start_date,str):
            start_date = pd.to_datetime(start_date,utc = True)
        if isinstance(stop_date,str):
            start_date = pd.to_datetime(stop_date,utc = True)
        if isinstance(channel,int):
            frequency = self.channel_frequencies[channel]
        elif channel in self.channel_frequencies:
            frequency = channel
        elif channel in 1e6*self.channel_frequencies:
            frequency = channel/1e6
        if sensor in self.sensor_hostnames:
            return self.data[(self.data['sensor_hostname']==sensor)&(self.data['channel_frequency_mhz']==frequency) &(self.data['timestamp']>start_date)&(self.data['timestamp']<stop_date)]
        elif sensor in self.sensor_names:
            return self.data[(self.data['sensor_name']==sensor)&(self.data['channel_frequency_mhz']==frequency) &(self.data['timestamp']>start_date)&(self.data['timestamp']<stop_date) ]
        else:
            return self.data      
