                    data_row = dict(fixed_data_row)
                    data_row["channel"] = capture_index
                    data_row["channel_frequency_mhz"] = capture['core:frequency']*1e-6
                    data_row["timestamp"] = pd.to_datetime(capture['core:datetime'])
