def summarize_by_month(top_directory,output_directory,exclude ="seadog08",include=None,force_new=False):
    "Reads top directory and organizes the summary by month of block names (may have some timestamps slightly after midnight)"
    file_names = os.listdir(top_directory)
    if include:
        file_names = [file_name for file_name in file_names if re.search(include,file_name,re.IGNORECASE)]
    if exclude:
        file_names = [file_name for file_name in file_names if not re.search(exclude,file_name,re.IGNORECASE)]
    block_files = list(filter(lambda x:re.match(BLOCK_MONTH_PATTERN,x),file_names))
    year_month_list = list(map(lambda x:"{year}_{month}".format(**re.match(BLOCK_MONTH_PATTERN,x).groupdict()),block_files)) 
    unique_months = list(set(year_month_list))
    month_dictionary = {month:[] for month in unique_months}
    destination_names = list(map(lambda x: os.path.join(output_directory,x),os.listdir(output_directory)))
    for index,year_month in enumerate(sorted(year_month_list)):
        month_dictionary[year_month].append(os.path.join(top_directory,block_files[index]))
    for key,value in month_dictionary.items():
        save_path = os.path.join(output_directory,key+".csv")
        if not force_new:
            if save_path in destination_names:
                continue
        create_summary_table_data_blocks(file_names=value,
                                         save=save_path)
        
def copy_and_rename(production_directory,output_directory,exclude = "seadog08|seadog10",include=None,force_new = False):
    """Opens a raw production directory and copies the contents to the teir2 data structure, updating the sensor name"""
    file_names = os.listdir(production_directory)
    if include:
        file_names = list(filter(lambda x:re.search(include,x),file_names))
    if exclude:
        file_names = list(filter (lambda x:not re.search(exclude,x),file_names))
    block_files = list(filter(lambda x:re.match(DATABLOCK_PATTERN,x),file_names))
    date_sensor_list = list(map(lambda x: re.match(DATABLOCK_PATTERN,x).groupdict(),block_files))
    destination_names = list(map(lambda x: os.path.join(output_directory,x),os.listdir(output_directory)))
    for day_sensor in date_sensor_list:
        clean_date = pd.to_datetime(day_sensor["date"])
        clean_date = clean_date.date()
        old_file_path = os.path.join(production_directory,f'{day_sensor["date"]}_{day_sensor["sensor_hostname"]}.zip')

        try:
            sensor_name = SENSOR_COMMON_NAMES[day_sensor["sensor_hostname"]]
        except KeyError:
            print(f"The file {old_file_path} has failed")
            continue
        new_file_path = os.path.join(output_directory,f'{clean_date}_{sensor_name}.zip')
        if not force_new:
            if new_file_path in destination_names:
                continue
        #print(old_file_path,new_file_path)
        try:
            shutil.copyfile(old_file_path,new_file_path)
        except Exception as e:
            print(e)

def save_all_psd(top_directory,output_directory,capture_statistics=["mean","median","95th_percentile","99th_percentile","max"],exclude=None,include=None,force_new = False):
    file_names = os.listdir(top_directory)
    if include:
        file_names = [file_name for file_name in file_names if re.search(include,file_name,re.IGNORECASE)]
    if exclude:
        file_names = [file_name for file_name in file_names if not re.search(exclude,file_name,re.IGNORECASE)]
    block_files = list(filter(lambda x:re.match(BLOCK_MONTH_PATTERN,x),file_names))
    destination_names=[]
    if not force_new:
        destination_names = os.listdir(output_directory)
        destination_names = list(map(lambda x:os.path.join(output_directory,x),destination_names))
    for file_name in block_files:
        match = re.match(DATABLOCK_PATTERN,file_name)
        sensor_name = match.groupdict()["sensor_hostname"]
        date = match.groupdict()["date"]
        if sensor_name in SENSOR_COMMON_NAMES.keys():
            sensor = SENSOR_COMMON_NAMES[sensor_name]
        elif sensor_name in SENSOR_COMMON_NAMES.values():
            sensor = sensor_name
        for capture_statistic in capture_statistics:
            psd_name = f"{date}_{sensor}_{capture_statistic}.csv"
            psd_path = os.path.join(output_directory,psd_name)
            if not force_new:
                if psd_path in destination_names:
                    continue
            try:
                day_block = DayBlock(file_path=os.path.join(top_directory,file_name))
                day_block.get_day_psd(capture_statistic=capture_statistic,save=psd_path)
            except Exception as e:
                print(f'File:{os.path.join(top_directory,file_name)} failed')
                print(e)

def save_all_pfp(top_directory,output_directory,capture_statistics=["mean"], 
                 detectors =["rms"],exclude=None, include=None,force_new = False):
    file_names = os.listdir(top_directory)
    if include:
        file_names = [file_name for file_name in file_names if re.search(include,file_name,re.IGNORECASE)]
    if exclude:
        file_names = [file_name for file_name in file_names if not re.search(exclude,file_name,re.IGNORECASE)]
    block_files = list(filter(lambda x:re.match(BLOCK_MONTH_PATTERN,x),file_names))
    destination_names=[]
    if not force_new:
        destination_names = os.listdir(output_directory)
        destination_names = list(map(lambda x:os.path.join(output_directory,x),destination_names))
    for file_name in block_files:
        match = re.match(DATABLOCK_PATTERN,file_name)
        sensor_name = match.groupdict()["sensor_hostname"]
        date = match.groupdict()["date"]
        if sensor_name in SENSOR_COMMON_NAMES.keys():
            sensor = SENSOR_COMMON_NAMES[sensor_name]
        elif sensor_name in SENSOR_COMMON_NAMES.values():
            sensor = sensor_name
        for capture_statistic in capture_statistics:
            for detector in detectors:
                pfp_name = f"PFP_{date}_{sensor}_{capture_statistic}_{detector}.csv"
                pfp_path = os.path.join(output_directory,pfp_name)
                if not force_new:
                    if pfp_path in destination_names:
                        continue
                try:
                    day_block = DayBlock(file_path=os.path.join(top_directory,file_name))
                    day_block.get_day_aligned_pfp(capture_statistic=capture_statistic,detector=detector,save=pfp_path)
                except Exception as e:
                    print(f'file: {os.path.join(top_directory,file_name)} failed')
                    print(e)


